/*
 * A040373  Continued fraction for sqrt(393).
 * https://oeis.org/A040373
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   continued fraction expansion of sqrt(393) using the standard
 *            recurrence for quadratic irrationals. a(0) = 19; subsequent
 *            terms are generated by the update equations for m, d and a. The
 *            sequence repeats with period 20, after the term 2*a0 = 38. For
 *            any n ≥ 0 the function returns the n-th partial q...
 * Range:     u8 none, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Periodic part after the initial term a0 = 19. */
    static seq_t period[128];
    static idx_t period_len = 0;

    if (period_len == 0)
    {
        const seq_t D   = 393;   /* The radicand. */
        const seq_t a0  = 19;    /* floor(sqrt(393)). */
        seq_t m = 0;
        seq_t d = 1;
        seq_t a = a0;
        idx_t pos = 0;

        /* Generate the continued fraction terms until the last term
           of the period (2*a0) appears. */
        do
        {
            m = d * a - m;                      /* m_{k+1} = d_k * a_k - m_k */
            d = (D - m * m) / d;                /* d_{k+1} = (D - m_{k+1}^2)/d_k */
            a = (a0 + m) / d;                   /* a_{k+1} = floor((a0 + m_{k+1}) / d_{k+1}) */
            period[pos++] = a;
        } while (a != 2 * a0);                  /* Term 2*a0 marks end of a period */

        period_len = pos;
    }

    /* The first term a(0) is not part of the period. */
    if (n == 0)
        return 19;
    return period[(n - 1) % period_len];
}
